// Categorize, add source_type, and prepare for insert
const categories = {
  '🧠 LLM': ['llm', 'gpt', 'claude', 'mistral', 'gemini', 'chatgpt', 'language model', 'large language'],
  '📚 RAG': ['rag', 'retrieval', 'embedding', 'vector', 'semantic search'],
  '🎨 Vision': ['image', 'diffusion', 'dall-e', 'midjourney', 'stable diffusion', 'vision', 'computer vision', 'image generation'],
  '🤖 Agents': ['agent', 'autonomous', 'agentic', 'workflow', 'swarm', 'multi-agent'],
  '💻 Coding': ['code', 'copilot', 'coding', 'cursor', 'github copilot', 'devin', 'programming', 'developer'],
  '🔬 Research': ['research', 'paper', 'arxiv', 'publication', 'study', 'breakthrough', 'academic']
};

const items = $input.all();
const output = [];

for (const item of items) {
  try {
    // Skip if no url or title
    if (!item.json.url || !item.json.title) {
      continue;
    }

    // Categorize by content
    const text = (
      (item.json.title || '') + ' ' + 
      (item.json.description || '') + ' ' + 
      (item.json.content || '')
    ).toLowerCase();

    let category = '🤖 AI General';
    for (const [cat, keywords] of Object.entries(categories)) {
      if (keywords.some(kw => text.includes(kw))) {
        category = cat;
        break;
      }
    }

    // Determine source_type based on source domain and URL
    const source = item.json.source || 'Unknown';
    const url = (item.json.url || '').toLowerCase();
    const sourceLower = source.toLowerCase();
    let source_type = 'Other';

    // Reddit Communities - Explicit Reddit domain check
    if (sourceLower.includes('reddit.com') || url.includes('reddit.com')) {
      source_type = 'Reddit Communities';
    }
    // Company Blogs - Official company blogs and announcements
    else if (
      sourceLower.includes('openai.com') || url.includes('openai.com') ||
      sourceLower.includes('anthropic.com') || url.includes('anthropic.com') ||
      sourceLower.includes('huggingface.co') || url.includes('huggingface.co') ||
      sourceLower.includes('blog.google') || url.includes('blog.google') ||
      sourceLower.includes('deepmind.google') || url.includes('deepmind.google') ||
      sourceLower.includes('ai.meta.com') || url.includes('ai.meta.com') ||
      sourceLower.includes('stability.ai') || url.includes('stability.ai') ||
      sourceLower.includes('cohere.com') || url.includes('cohere.com') ||
      sourceLower.includes('mistral.ai') || url.includes('mistral.ai')
    ) {
      source_type = 'Company Blogs';
    }
    // Tech News - Tech news sites, GitHub projects, tools, packages
    else if (
      sourceLower.includes('techcrunch') || url.includes('techcrunch') ||
      sourceLower.includes('hnrss.org') || url.includes('hnrss.org') ||
      sourceLower.includes('news.ycombinator') || url.includes('news.ycombinator') ||
      sourceLower.includes('github.com') || url.includes('github.com') ||
      sourceLower.includes('github.io') || url.includes('github.io') ||
      text.includes('github') || text.includes('package') || 
      text.includes('library') || text.includes('framework') ||
      text.includes('tool') || text.includes('release')
    ) {
      source_type = 'Tech News';
    }

    // Add category, source_type and pass through
    output.push({
      json: {
        url: item.json.url,
        title: item.json.title,
        description: item.json.description || '',
        content: item.json.content || '',
        source: source,
        source_type: source_type,
        category: category,
        published_at: item.json.published_at || new Date().toISOString()
      }
    });
  } catch (error) {
    // Skip problematic items
    continue;
  }
}

return output;

