  if (description.length <= maxLength) return description;

  // Essayer de couper à la fin d'une phrase
  const cutPoint = description.lastIndexOf('.', maxLength - 3);
  if (cutPoint > maxLength * 0.7) { // Si on trouve un point pas trop loin
    return description.substring(0, cutPoint + 1);
  }

  // Sinon couper proprement
  return description.substring(0, maxLength - 3) + '...';
}

