const items = $input.all();
const articles = $('Escape SQL Values1').all();

console.log(`📥 Traitement de ${items.length} articles`);

const output = [];
let maxTokensCount = 0;
let tooShortCount = 0;
let successCount = 0;

for (let i = 0; i < items.length; i++) {
  const article = articles[i]?.json || {};

  let score = 0;
  let confidence = 0;
  let reason = 'Parsing error';
  let aiTag = '';
  let aiSummary = '';
  let aiTakeaway = '';

  try {
    const candidate = items[i].json.candidates[0];
    const finishReason = candidate.finishReason;
    const text = candidate.content.parts[0].text;

    // Vérifier si MAX_TOKENS
    if (finishReason === 'MAX_TOKENS') {
      maxTokensCount++;

      // Si le texte est trop court (< 20 chars), impossible de parser
      if (text.length < 20) {
        tooShortCount++;
        console.log(`⚠️  Article ${i}: MAX_TOKENS avec texte trop court (${text.length} chars) - SKIP`);
        reason = 'MAX_TOKENS - Response too short to parse';
        // On laisse confidence=0 pour filtrer cet article

      } else {
        // Tenter de parser quand même
        const clean = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

        try {
          const parsed = JSON.parse(clean);
          score = parsed.score || 0;
          confidence = parsed.confidence || 50; // Confiance moyenne
          reason = 'Parsed despite MAX_TOKENS';
          successCount++;
        } catch {
          // Échec de parsing mais on garde une trace
          reason = 'MAX_TOKENS - Could not parse incomplete JSON';
          confidence = 0; // Sera filtré
        }
      }

    } else {
      // Cas normal : STOP
      const clean = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
      const parsed = JSON.parse(clean);

      score = parsed.score || 0;
      confidence = parsed.confidence || 0;
      reason = parsed.reason || 'OK';
      aiTag = parsed.ai_tag || '';
      aiSummary = parsed.ai_summary || '';
      aiTakeaway = parsed.ai_takeaway || '';

      // Valider
      score = Math.max(0, Math.min(100, Number(score) || 0));
      confidence = Math.max(0, Math.min(100, Number(confidence) || 0));

      successCount++;
    }

  } catch (error) {
    console.log(`❌ Article ${i}: ${error.message}`);
  }

  output.push({
    json: {
      ...article,
      gemini_score: score,
      gemini_confidence: confidence,
      gemini_reason: reason,
      ai_tag: aiTag,
      ai_summary: aiSummary,
      ai_takeaway: aiTakeaway
    }
  });
}

// Filtrage
const filtered = output.filter(item => item.json.gemini_confidence >= 85);

